import os
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.bts_kpi_report_generator import bts_kpi_report_generator  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure  # type: ignore


class KPIReport(object):
    def __init__(self, log_dir=None, report_log_dir=None):
        self.log_dir = log_dir if log_dir else str(tc.output_dir)
        self.report_log_dir = report_log_dir if report_log_dir else os.path.join(self.log_dir, 'report')
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)

    def __call__(self):
        pmstats_locations = self._get_all_pmstats_locations()
        generate_kpi_report_params = tc.run_params['generate_kpi_report']

        source_kpi_file = generate_kpi_report_params['source_kpi_file']
        if not source_kpi_file:
            source_kpi_file = "{}.yaml".format(tc.bts_release)

        for pmstats_location in pmstats_locations:
            self._unpack_pm_files(pm_location=pmstats_location, destination_dir=pmstats_location)
            bts_kpi_report_generator.generate_kpi_report(
                path_dir=pmstats_location,
                source_kpi=source_kpi_file,
                kpi_to_generate=generate_kpi_report_params['kpi_targets'],
                build=tc.bts_build,
                generate_html_xlsx=True,
                generate_json=True,
                number_of_start_intervals_to_skip=generate_kpi_report_params['skip_start'],
                number_of_end_intervals_to_skip=generate_kpi_report_params['skip_end']
            )

    def _get_all_pmstats_locations(self):
        pmstats_locations = None

        any_device = "*"
        pmstats_location_regex = os.path.join(self.log_dir, "report", any_device, 'pmstats')

        try:
            ls_output = self.unix_local.ls(options="-d {}".format(pmstats_location_regex))
            pmstats_locations = ls_output['files'].keys()

        except (CommandFailure, KeyError) as error:
            MolerTest.warning(msg="PMstats are not available. Skipping generating report...")
            MolerTest.warning(msg=error)

        return pmstats_locations

    def _unpack_pm_files(self, pm_location, destination_dir):
        """
        Unpack archive with pm files on UnixLocal.

        :param destination_dir:
        :return:
        """

        unzip = self.unix_local.device.get_cmd(cmd_name='unzip',
                                               cmd_params={'zip_file': os.path.join(pm_location, "*.zip"),
                                                           'extract_dir': destination_dir, 'overwrite': True})
        unzip(timeout=120)

        self.unix_local.device.run(cmd_name='rm',
                                   cmd_params={'file': os.path.join(pm_location, "*.zip")})
